(window.webpackJsonp=window.webpackJsonp||[]).push([[6],{"3XHS":function(e,a,n){"use strict";n.r(a);var t=n("q1tI"),s=n.n(t),i=n("Bl7J"),o=n("vrFN"),r=n("nd+B"),c=n.n(r);a.default=function(){return s.a.createElement(i.a,null,s.a.createElement(o.a,{keywords:["Bryan Cee","music","composer","Reggae","Classical"],title:"About"}),s.a.createElement("div",{className:"sm:flex pt-8"},s.a.createElement("section",{className:"text-center w-full sm:w-7/12"},s.a.createElement("img",{alt:"Bryan enjoying the piano.",className:"block",src:c.a})),s.a.createElement("section",{className:"bg-gray-200 p-4 mt-8 w-full sm:w-5/12 xxxmt-8"},s.a.createElement("h1",{className:"font-bold text-xl mb-4"},"Bryan Cee..."),s.a.createElement("p",{className:"text-sm mb-4"},"Brian Cooper also affectionately known as “Bryan Cee” is an International singer, songwriter, musician, composer and educator who has performed both locally and abroad. Some of his works have been featured by the Bahamas Ministry of Tourism as well as the Bahamas Ministry of Education. As a performer, Brian has performed many festivals such as the Caribbean carnival where he was featured in The Bahamas, Atlanta, and Minnesota. Brian has also made a name for himself in the midwest where he performed extensively in Iowa, Wisconsin, and Minnesota. Some venues included The Global market festival, Secret Circus, Winter Carnival, and St. Paul’s Riverfront prototype festival. By 2016 he completed his first album called “The Wibe Of life” which included his first single “Long Lost Brother” which was released with a music video in late 2012."),s.a.createElement("p",{className:"text-sm mb-4"},"By being exposed to classical music from a very young age, he grew fond of the piano and began his studies eventually receiving his Bachelor’s degree in music studies from St. Johns University, majoring in Piano, Organ, and Tuba. Brian also has done many classical concerts for both organ and piano featuring works from Bach, Beethoven, Schumann, Einaudi, and Buxtehude along with many original compositions. Raised catholic, Brian began his musical journey in the church where he held the position of organist and musical director of his local parish for over 10 years. As an educator and artist-teacher for more than 15 years, Brian has taught k-12 to the college level. Some of his duties were vocal coach, private piano instructor, choir/ band director as well as starting a youth orchestra. After attaining a master’s in piano performance at McNally Smith College of music, Brian expanded his talents to Chicago’s theater scene as a pit musician as well as working directly with CPS schools as a musical director and accompanist under the Professional Dance Theater Youth Acadamy Company (P.D.T.Y.A)."))))}},"nd+B":function(e,a,n){e.exports=n.p+"static/bryan-piano-pt-57af9d6e3b65cadd263327cbb6bcec81.jpg"}}]);
